import { forwardRef, useImperativeHandle, useCallback } from "react";
import type { AnimatedIconHandle, AnimatedIconProps } from "./types";
import { motion, useAnimate } from "motion/react";

type CustomAnimation = {
  airPlaneDuration: number;
  windDuration: number;
  exitDuration: number;
};

const AirplaneIcon = forwardRef<
  AnimatedIconHandle,
  AnimatedIconProps & CustomAnimation
>(
  (
    {
      size = 24,
      color = "currentColor",
      strokeWidth = 2,
      className = "",
      airPlaneDuration = 0.3,
      windDuration = 0.8,
      exitDuration = 0.3,
    },
    ref,
  ) => {
    const [scope, animate] = useAnimate();

    const start = useCallback(async () => {
      // Subtle vibration for the plane
      animate(
        ".airplane",
        { x: [0, 0.5, 0], y: [0, -0.5, 0] },
        { duration: airPlaneDuration },
      );

      // Streak 1: Upper Wing (Top-right streak)
      animate(
        ".wind1",
        {
          x: -12,
          y: 24,
          opacity: 1,
        },
        { duration: windDuration, ease: "easeOut" },
      );

      // Streak 2: Lower Wing (Middle-left streak)
      animate(
        ".wind2",
        {
          x: 0,
          y: 26,
          opacity: 1,
        },
        { duration: windDuration, ease: "easeOut", delay: 0.2 },
      );
    }, [animate, airPlaneDuration, windDuration]);

    const stop = useCallback(async () => {
      animate(".airplane", { x: 0, y: 0 }, { duration: exitDuration });
      animate(
        ".wind1",
        { opacity: 0, x: 12, y: -4 },
        { duration: exitDuration },
      );
      animate(
        ".wind2",
        { opacity: 0, x: 26, y: 8 },
        { duration: exitDuration },
      );
    }, [animate, exitDuration]);

    useImperativeHandle(
      ref,
      () => ({
        startAnimation: start,
        stopAnimation: stop,
      }),
      [start, stop],
    );

    return (
      <motion.svg
        ref={scope}
        xmlns="http://www.w3.org/2000/svg"
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="none"
        stroke={color}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeLinejoin="round"
        className={`cursor-pointer ${className}`}
        onHoverStart={start}
        onHoverEnd={stop}
      >
        <motion.path
          className="airplane"
          d="M13.617 1.53c.926-.747 1.964-.793 3.097-.777.587.009.88.013 1.115.104.373.145.67.442.815.815.09.235.095.528.104 1.115.016 1.133-.03 2.17-.778 3.097-.63.78-1.714 1.188-2.235 2.05-.398.656-.213 1.337-.042 2.038l1.28 5.245c.255 1.046.06 1.715-.67 2.446-.39.39-.713.37-1.028-.133l-3.862-6.154-1.845 1.466c-.67.532-1.003.798-1.18 1.172-.41.876-.15 2.192-.136 3.142.008.525-.446 1.56-1.088 1.594-.396.022-.531-.452-.66-.743l-1.232-2.802c-.294-.67-.306-.682-.976-.976l-2.802-1.233c-.29-.128-.765-.263-.743-.66.035-.641 1.07-1.095 1.594-1.087.95.013 2.266.274 3.142-.137.374-.176.64-.51 1.172-1.18l1.466-1.844L1.97 4.226c-.503-.316-.522-.64-.133-1.028.73-.73 1.4-.925 2.446-.67l5.245 1.28c.7.17 1.382.356 2.039-.042.86-.52 1.269-1.604 2.049-2.235"
        />

        <motion.path
          className="wind1"
          initial={{ opacity: 0, x: 10, y: -6 }}
          d="m.5 3.5 3-3"
        ></motion.path>
        <motion.path
          className="wind2"
          initial={{ opacity: 0, x: 26, y: 8 }}
          d="m.5 3.5 3-3"
        ></motion.path>
      </motion.svg>
    );
  },
);

AirplaneIcon.displayName = "AirplaneIcon";
export default AirplaneIcon;

import { forwardRef, useImperativeHandle, useRef } from "react";
import type {
  AnimatedIconHandle,
  AnimatedIconProps,
  IconEasing,
} from "./types";
import { motion, useAnimate } from "motion/react";

type CustomStyleProps = {
  stiffness?: number;
  damping?: number;
  durationY?: number;
  durationX?: number;
  ease?: IconEasing;
};

const AlarmClockPlusIcon = forwardRef<
  AnimatedIconHandle,
  AnimatedIconProps & CustomStyleProps
>(
  (
    {
      size = 24,
      color = "currentColor",
      strokeWidth = 2,
      className = "",
      stiffness = 200,
      damping = 25,
      durationY = 0.2,
      durationX = 0.3,
      ease = "linear",
      ...props
    },
    ref,
  ) => {
    const [scope, animate] = useAnimate();
    const animationControls = useRef<Array<ReturnType<typeof animate>>>([]);

    const start = async () => {
      animationControls.current.forEach((control) => control.stop());
      animationControls.current = [];

      animationControls.current.push(
        animate(
          ".clock",
          {
            y: -1.5,
            x: [-1, 1, -1, 1, -1, 0],
          },
          {
            y: {
              duration: durationY,
              type: "spring",
              stiffness: stiffness,
              damping: damping,
            },
            x: { duration: durationX, repeat: Infinity, ease: ease },
          },
        ),
      );

      animationControls.current.push(
        animate(
          ".bells",
          {
            y: -2.5,
            x: [-2, 2, -2, 2, -2, 0],
          },
          {
            y: {
              duration: durationY,
              type: "spring",
              stiffness: stiffness,
              damping: damping,
            },
            x: { duration: durationX, repeat: Infinity, ease: ease },
          },
        ),
      );

      await animate(
        ".plus",
        { scale: [1, 1.2, 1] },
        { duration: durationY, ease: "easeOut" },
      );
    };

    const stop = () => {
      animationControls.current.forEach((control) => control.stop());
      animationControls.current = [];

      animate(".clock", { y: 0, x: 0 }, { duration: durationY * 2 });
      animate(".bells", { y: 0, x: 0 }, { duration: durationY * 2 });
    };

    useImperativeHandle(ref, () => {
      return {
        startAnimation: start,
        stopAnimation: stop,
      };
    });

    // 🖱 hover logic (only when NOT controlled)
    const handleHoverStart = () => {
      start();
    };

    const handleHoverEnd = () => {
      stop();
    };

    return (
      <motion.svg
        ref={scope}
        onHoverStart={handleHoverStart}
        onHoverEnd={handleHoverEnd}
        xmlns="http://www.w3.org/2000/svg"
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="none"
        stroke={color}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeLinejoin="round"
        className={`cursor-pointer ${className}`}
        style={{ overflow: "visible" }}
        aria-hidden="true"
        {...props}
      >
        <motion.circle className="clock" cx="12" cy="13" r="8" />
        <motion.path
          className="bells"
          style={{ transformOrigin: "3.5px 4.5px" }}
          d="M5 3 2 6"
        />
        <motion.path
          className="bells"
          style={{ transformOrigin: "20.5px 4.5px" }}
          d="m22 6-3-3"
        />
        <motion.path className="clock" d="M6.38 18.7 4 21" />
        <motion.path className="clock" d="M17.64 18.67 20 21" />
        <motion.g className="plus" style={{ transformOrigin: "12px 13px" }}>
          <path d="M12 10v6" />
          <path d="M9 13h6" />
        </motion.g>
      </motion.svg>
    );
  },
);

AlarmClockPlusIcon.displayName = "AlarmClockPlusIcon";

export default AlarmClockPlusIcon;

