const WhatsappIcon = forwardRef<AnimatedIconHandle, AnimatedIconProps>(
  (
    { size = 24, color = "currentColor", strokeWidth = 2, className = "" },
    ref,
  ) => {
    const [scope, animate] = useAnimate();

    const start = useCallback(async () => {
      await animate(
        ".phone-icon",
        {
          rotate: [0, -15, 15, -10, 10, 0],
        },
        {
          duration: 0.4,
          ease: "easeInOut",
        },
      );
    }, [animate]);

    const stop = useCallback(() => {
      animate(
        ".phone-icon",
        {
          rotate: 0,
        },
        {
          duration: 0.2,
          ease: "easeOut",
        },
      );
    }, [animate]);

    useImperativeHandle(ref, () => ({
      startAnimation: start,
      stopAnimation: stop,
    }));

    return (
      <motion.svg
        ref={scope}
        onHoverStart={start}
        onHoverEnd={stop}
        xmlns="http://www.w3.org/2000/svg"
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="none"
        stroke={color}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeLinejoin="round"
        className={`cursor-pointer ${className}`}
      >
        <path stroke="none" d="M0 0h24v24H0z" fill="none" />
        <path d="M3 21l1.65 -3.8a9 9 0 1 1 3.4 2.9l-5.05 .9" />
        <motion.path
          className="phone-icon"
          style={{ transformOrigin: "50% 50%" }}
          d="M9 10a.5 .5 0 0 0 1 0v-1a.5 .5 0 0 0 -1 0v1a5 5 0 0 0 5 5h1a.5 .5 0 0 0 0 -1h-1a.5 .5 0 0 0 0 1"
        />
      </motion.svg>
    );
  },
);

WhatsappIcon.displayName = "WhatsappIcon";
export default WhatsappIcon;

"use client"

import * as React from "react"
import { useReducedMotion } from "motion/react"

import type { AnimatedIconHandle, AnimatedIconProps } from "./types"

/**
 * Keeps vendored ItsHover icons static when the user requests reduced motion,
 * without modifying the upstream SVG and animation source files.
 */
function withReducedMotion<Props extends AnimatedIconProps>(
  Icon: React.ForwardRefExoticComponent<
    Props & React.RefAttributes<AnimatedIconHandle>
  >
) {
  function ReducedMotionIcon(
    props: Props & { ref?: React.Ref<AnimatedIconHandle> }
  ) {
    const { ref, ...iconProps } = props
    const label = props["aria-label"]
    const reduceMotion = useReducedMotion()
    const iconRef = React.useRef<AnimatedIconHandle>(null)

    React.useImperativeHandle(
      ref,
      () => ({
        startAnimation: () => {
          if (!reduceMotion) iconRef.current?.startAnimation()
        },
        stopAnimation: () => {
          if (!reduceMotion) iconRef.current?.stopAnimation()
        },
      }),
      [reduceMotion]
    )

    return (
      <span
        data-reduced-motion={reduceMotion || undefined}
        className={
          reduceMotion ? "inline-flex [&>*]:pointer-events-none" : "contents"
        }
        aria-hidden={label ? undefined : true}
        aria-label={label}
        role={label ? "img" : undefined}
      >
        <Icon ref={iconRef} {...(iconProps as Props)} />
      </span>
    )
  }

  return ReducedMotionIcon
}

export { withReducedMotion }

import { forwardRef, useImperativeHandle, useCallback } from "react";
import type { AnimatedIconHandle, AnimatedIconProps } from "./types";
import { motion, useAnimate } from "motion/react";

const WorldIcon = forwardRef<AnimatedIconHandle, AnimatedIconProps>(
  (
    { size = 24, color = "currentColor", strokeWidth = 2, className = "" },
    ref,
  ) => {
    const [scope, animate] = useAnimate();

    const start = useCallback(async () => {
      // Rotate the globe
      animate(
        ".world-meridians",
        {
          pathLength: [0, 1],
        },
        {
          duration: 1,
          ease: "linear",
        },
      );
    }, [animate]);

    const stop = useCallback(async () => {
      animate(
        ".world-meridians",
        {
          pathLength: 1,
        },
        {
          duration: 0.2,
          ease: "easeInOut",
        },
      );
    }, [animate]);

    useImperativeHandle(ref, () => ({
      startAnimation: start,
      stopAnimation: stop,
    }));

    return (
      <motion.svg
        ref={scope}
        xmlns="http://www.w3.org/2000/svg"
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="none"
        stroke={color}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeLinejoin="round"
        className={`cursor-pointer ${className}`}
        onHoverStart={start}
        onHoverEnd={stop}
      >
        <path stroke="none" d="M0 0h24v24H0z" fill="none" />

        {/* Globe circle */}
        <motion.path
          d="M3 12a9 9 0 1 0 18 0a9 9 0 0 0 -18 0"
          className="world-globe"
          style={{ transformOrigin: "50% 50%" }}
        />

        {/* Horizontal lines and meridians */}
        <motion.g
          className="world-meridians"
          style={{ transformOrigin: "50% 50%" }}
        >
          <motion.path d="M3.6 9h16.8" className="world-meridians" />
          <motion.path d="M3.6 15h16.8" className="world-meridians" />
          <motion.path
            d="M11.5 3a17 17 0 0 0 0 18"
            className="world-meridians"
          />
          <motion.path
            d="M12.5 3a17 17 0 0 1 0 18"
            className="world-meridians"
          />
        </motion.g>
      </motion.svg>
    );
  },
);

WorldIcon.displayName = "WorldIcon";
export default WorldIcon;

import { forwardRef, useImperativeHandle, useCallback } from "react";
import type { AnimatedIconHandle, AnimatedIconProps } from "./types";
import { motion, useAnimate } from "motion/react";

const YoutubeIcon = forwardRef<AnimatedIconHandle, AnimatedIconProps>(
  (
    { size = 24, color = "currentColor", strokeWidth = 2, className = "" },
    ref,
  ) => {
    const [scope, animate] = useAnimate();

    const start = useCallback(async () => {
      await animate(
        ".youtube-play",
        {
          pathLength: [0, 1],
        },
        {
          duration: 0.3,
          ease: "easeInOut",
        },
      );

      animate(
        ".youtube-play",
        {
          scale: [1, 0.8, 1],
        },
        {
          duration: 0.3,
          ease: "easeInOut",
        },
      );
    }, [animate]);

    const stop = useCallback(async () => {
      animate(
        ".youtube-play",
        {
          scale: 1,
          x: 0,
        },
        {
          duration: 0.3,
          ease: "easeInOut",
        },
      );

      animate(
        ".youtube-frame",
        {
          scale: 1,
        },
        {
          duration: 0.2,
          ease: "easeOut",
        },
      );
    }, [animate]);

    useImperativeHandle(ref, () => ({
      startAnimation: start,
      stopAnimation: stop,
    }));

    return (
      <motion.svg
        ref={scope}
        xmlns="http://www.w3.org/2000/svg"
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="none"
        stroke={color}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeLinejoin="round"
        className={`cursor-pointer ${className}`}
        onHoverStart={start}
        onHoverEnd={stop}
      >
        <path stroke="none" d="M0 0h24v24H0z" fill="none" />

        <motion.path
          d="M2 8a4 4 0 0 1 4 -4h12a4 4 0 0 1 4 4v8a4 4 0 0 1 -4 4h-12a4 4 0 0 1 -4 -4v-8z"
          className="youtube-frame"
          style={{ transformOrigin: "50% 50%" }}
        />

        <motion.path
          d="M10 9l5 3l-5 3z"
          className="youtube-play"
          style={{ transformOrigin: "50% 50%" }}
        />
      </motion.svg>
    );
  },
);

YoutubeIcon.displayName = "YoutubeIcon";
export default YoutubeIcon;
